FEATURE_DESCS.update({
    'Bonus Cantrip (Light Domain)': "You learn the Light cantrip if you don't already know it. It doesn't count against your number of cantrips known.",
    'Bonus Cantrip (Circle of the Land)': "Gain one additional Druid cantrip of your choice.",
})

FEATURE_DESCS.update({
    'Creative Crescendo': "Prerequisite: 14th level. You can have a number of animated objects from Animating Performance equal to your CHA modifier at once (only one can be Large, the rest Small or smaller), rather than just one.",
})

FEATURE_DESCS.update({
    'Radiant Consumption': "Bonus action, 1 minute: glow with a 10-ft radiant aura that deals damage equal to half your level to each creature in it (including you) at the end of your turn; once per turn, deal extra radiant damage equal to your level on a hit. Usable once per long rest.",
})

