def get_tool_tooltip(tool_name: str) -> str:
    """Resolve a tool proficiency name to its full description. Falls back
    to the generic "Musical instrument"/"Gaming set" text for a specific
    named instrument or game (e.g. "Lute", "Dice set") not individually
    listed in TOOL_TOOLTIPS, since they all share the same mechanical text
    per the source — avoids duplicating that text 10 and 4 times over."""
    if tool_name in TOOL_TOOLTIPS:
        return TOOL_TOOLTIPS[tool_name]
    from dnd_app.data.items import INSTRUMENT_TOOLS, GAMING_SETS
    if tool_name in INSTRUMENT_TOOLS:
        return TOOL_TOOLTIPS["Musical instrument"]
    if tool_name in GAMING_SETS:
        return TOOL_TOOLTIPS["Gaming set"]
    return ""
